package edu.campus.lostfound.service;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;
import edu.campus.lostfound.domain.*;
import edu.campus.lostfound.repository.*;
import java.time.LocalDate;
import java.time.LocalTime;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
@ExtendWith(MockitoExtension.class) class MatchingServiceTest {
 @Mock ReportRepository reports;
 @Mock MatchRepository matches;
 @Mock NotificationRepository notifications;
 private MatchingService service(){return new MatchingService(reports,matches,notifications,.25,.35,.25,.15,.55,30);}
 @Test void matchingItemDetailsRemainStrongDespiteDifferentTitles(){var s=service();var a=report(ReportType.LOST,"Black wallet","wallet black leather","Main Library",LocalDate.parse("2026-09-20"),LocalTime.of(10,0));var b=report(ReportType.FOUND,"Wallet found","black leather wallet","Main Library",LocalDate.parse("2026-09-20"),LocalTime.of(10,0));var r=s.score(a,b);assertEquals(93,r.score(),0.01);assertEquals(100,r.categoryScore(),0.01);assertEquals(80,r.descriptionScore(),0.01);assertTrue(r.explanation().contains("Category 100/100"));}
 @Test void synonymCategoryAndPartialLocationHaveDocumentedSimilarity(){var r=service().score(reportWithCategory(ReportType.LOST,"Phone","Phone","black case","Main Library",LocalDate.parse("2026-09-20"),null),reportWithCategory(ReportType.FOUND,"Mobile","Mobile phone","blue black case","Main Library desk",LocalDate.parse("2026-09-20"),null));assertEquals(100,r.categoryScore(),0.01);assertEquals(75,r.locationScore(),0.01);}
 @Test void titleAndDescriptionBothContributeToTextSimilarity(){var r=service().score(report(ReportType.LOST,"Black leather wallet","black leather wallet","Library",LocalDate.parse("2026-09-20"),null),report(ReportType.FOUND,"Black leather wallet","black wallet","Library",LocalDate.parse("2026-09-20"),null));assertEquals(88,r.descriptionScore(),.01);assertTrue(r.explanation().contains("title 100/100"));assertTrue(r.explanation().contains("description 80/100"));}
 @Test void matchingTitleRaisesScoreWhenReportDescriptionsUseDifferentWords(){var lost=report(ReportType.LOST,"Black leather wallet","brass snap and two card slots","Main Library",LocalDate.parse("2026-09-20"),null);var titleMatch=report(ReportType.FOUND,"Black leather wallet","found near the reading tables","Main Library",LocalDate.parse("2026-09-20"),null);var noTitleMatch=report(ReportType.FOUND,"Small personal item","found near the reading tables","Main Library",LocalDate.parse("2026-09-20"),null);assertTrue(service().score(lost,titleMatch).score()>service().score(lost,noTitleMatch).score());}
 @Test void reorderedLocationWordsStillScoreAsAFullTokenMatch(){var r=service().score(report(ReportType.LOST,"wallet","black wallet","Central Library Level Two",LocalDate.parse("2026-09-20"),null),report(ReportType.FOUND,"wallet","black wallet","Level Two Central Library",LocalDate.parse("2026-09-20"),null));assertEquals(100,r.locationScore(),.01);}
 @Test void dateTimeSimilarityUsesOptionalTime(){var a=report(ReportType.LOST,"wallet","same details","Library",LocalDate.parse("2026-09-20"),LocalTime.of(10,0));var b=report(ReportType.FOUND,"wallet","same details","Library",LocalDate.parse("2026-09-20"),LocalTime.of(11,0));var withTime=service().score(a,b);var withoutTime=service().score(report(ReportType.LOST,"wallet","same details","Library",LocalDate.parse("2026-09-20"),null),report(ReportType.FOUND,"wallet","same details","Library",LocalDate.parse("2026-09-20"),null));assertTrue(withTime.dateTimeScore()<withoutTime.dateTimeScore());}
 @Test void distantDatesRemoveDateContribution(){var r=service().score(report(ReportType.LOST,"wallet","black wallet","Library",LocalDate.parse("2026-01-01"),null),report(ReportType.FOUND,"wallet","black wallet","Library",LocalDate.parse("2026-03-01"),null));assertEquals(0,r.dateTimeScore(),0.01);assertEquals(85,r.score(),0.01);}
 @Test void weightsProduceExpectedWeightedTotal(){var r=service().score(report(ReportType.LOST,"wallet","black wallet","Library",LocalDate.parse("2026-09-20"),null),report(ReportType.FOUND,"wallet","black wallet","Library",LocalDate.parse("2026-09-20"),null));assertEquals(100,r.score(),0.01);}
 @Test void missingOptionalTimesRemainScorable(){var r=service().score(report(ReportType.LOST,"wallet","black wallet","Library",LocalDate.parse("2026-09-20"),null),report(ReportType.FOUND,"wallet","black wallet","Library",LocalDate.parse("2026-09-20"),null));assertEquals(100,r.dateTimeScore(),0.01);assertTrue(r.explanation().contains("time not supplied"));}
 @Test void scoreIsBoundedAtOneHundred(){var r=service().score(report(ReportType.LOST,"wallet","black wallet","Library",LocalDate.parse("2026-09-20"),null),report(ReportType.FOUND,"wallet","black wallet","Library",LocalDate.parse("2026-09-20"),null));assertTrue(r.score()>=0&&r.score()<=100);}
 @Test void oppositeTypeAboveThresholdCreatesMatchAndNotifications(){var s=service();var found=report(ReportType.FOUND,"wallet","black wallet","Library",LocalDate.parse("2026-09-20"),null);var lost=report(ReportType.LOST,"wallet","black wallet","Library",LocalDate.parse("2026-09-20"),null);when(reports.findByTypeAndStatusOrderByCreatedAtDesc(ReportType.LOST,ReportStatus.OPEN)).thenReturn(List.of(lost));when(matches.existsByLostReportIdAndFoundReportId(null,null)).thenReturn(false);s.process(found);verify(matches).save(any(PotentialMatch.class));verify(notifications,times(2)).save(any(Notification.class));}
 @Test void belowThresholdDoesNotPersistMatch(){var weak=report(ReportType.LOST,"book","novel red cover","Gym",LocalDate.parse("2026-09-20"),null);var found=report(ReportType.FOUND,"phone","blue screen cracked","Lab",LocalDate.parse("2026-09-20"),null);when(reports.findByTypeAndStatusOrderByCreatedAtDesc(ReportType.LOST,ReportStatus.OPEN)).thenReturn(List.of(weak));when(matches.existsByLostReportIdAndFoundReportId(null,null)).thenReturn(false);service().process(found);verify(matches,never()).save(any());}
 @Test void duplicateMatchPairIsNotStoredTwice(){var lost=report(ReportType.LOST,"wallet","black wallet","Library",LocalDate.parse("2026-09-20"),null);var found=report(ReportType.FOUND,"wallet","black wallet","Library",LocalDate.parse("2026-09-20"),null);when(reports.findByTypeAndStatusOrderByCreatedAtDesc(ReportType.LOST,ReportStatus.OPEN)).thenReturn(List.of(lost));when(matches.existsByLostReportIdAndFoundReportId(null,null)).thenReturn(true);service().process(found);verify(matches,never()).save(any());}
 @Test void invalidWeightsAreRejected(){assertThrows(IllegalArgumentException.class,()->new MatchingService(reports,matches,notifications,.2,.2,.2,.2,.5,30));}
 private ItemReport report(ReportType type,String title,String description,String location,LocalDate date,LocalTime time){return new ItemReport(type,title,"Accessories",description,location,date,time,new AppUser("Tester","test@example.org","hash",Role.USER));}
 private ItemReport reportWithCategory(ReportType type,String title,String category,String description,String location,LocalDate date,LocalTime time){return new ItemReport(type,title,category,description,location,date,time,new AppUser("Tester","test@example.org","hash",Role.USER));}
}
